// Generates web/auth-config.json from the private test/.env.
//
// The output contains ONLY the values that are public by design — the
// Supabase project URL and the publishable (client-safe) key. The same two
// values are already handed to every browser by GET /api/config; this file
// exists so the sign-in/sign-up pages can initialize Supabase even when the
// API process is not running. The secret key is never read or written here.
//
// The generated file is git-ignored; regenerate it with `npm run gen-auth-config`.

const fs = require('fs');
const path = require('path');

const envPath = path.resolve(__dirname, '..', '..', 'test', '.env');
const outPath = path.resolve(__dirname, '..', 'web', 'auth-config.json');

function readEnvValue(name) {
  if (!fs.existsSync(envPath)) return undefined;
  for (const line of fs.readFileSync(envPath, 'utf8').split(/\r?\n/)) {
    const match = line.match(/^([A-Z_]+)\s*=\s*(.*)$/);
    if (match && match[1] === name) {
      return match[2].replace(/^["']|["']$/g, '').trim();
    }
  }
  return undefined;
}

const supabaseUrl = readEnvValue('SUPABASE_URL');
const publishable = readEnvValue('SUPABASE_PUBLISHABLE_KEY');

if (!supabaseUrl || !publishable) {
  console.error('gen_auth_config: SUPABASE_URL / SUPABASE_PUBLISHABLE_KEY not found in', envPath);
  process.exit(1);
}

fs.writeFileSync(outPath, JSON.stringify(
  {
    configured: true,
    supabaseUrl,
    supabasePublishableKey: publishable,
    _note: 'Generated by tool/gen_auth_config.js from test/.env. Public client values only — never add the secret key here.',
  },
  null,
  2,
) + '\n');
console.log('gen_auth_config: wrote', outPath);
